(107, '巴黎咖啡時光', 'paris-guide-2-107', '<h2>巴黎・咖啡時光</h2>
<p>本篇帶你用一天的節奏認識巴黎，主題聚焦「咖啡時光」。文中穿插實地照片，方便對照路線與氛圍。圖片皆來自本站整理之城市圖庫。</p>
